/**
 * Component-scope `let` bindings written only by event handlers, in every
 * write form: a prefix and a postfix update, a compound assignment, a
 * destructuring swap, and a `for (let i …)` loop. The handlers read and
 * write the init body's locals, and the markup's `{nextId}` renders the
 * declared value `0` on SSR and in the client template alike: a handler's
 * write runs after render, so it does not stop the template from inlining
 * the declared value.
 *
 * Snapshots in `__snapshots__/handler-written-locals.{html,client.js}` are
 * regenerated by `bun run packages/adapter-tests/scripts/snapshot.ts
 * handler-written-locals`.
 */

import { defineSharedFixture, type SharedFixtureSpec } from './_helpers'

export const spec: SharedFixtureSpec = {
  id: 'handler-written-locals',
  componentName: 'HandlerWrittenLocals',
  sourceRoot: 'fixture',
  description:
    'component-scope lets written by event handlers (++x, x++, x += …, [a, b] = [b, a]) stay init locals and still render their declared value',
  interactions: [
    { type: 'expectText', selector: '.next', text: '0' },
    { type: 'click', selector: '.add-pre' },
    { type: 'expectText', selector: '.log', text: '#1' },
    { type: 'click', selector: '.add-post' },
    { type: 'expectText', selector: '.log', text: '#1 #1' },
    { type: 'click', selector: '.swap' },
    { type: 'expectText', selector: '.log', text: '#1 #1 ba' },
    // nextId is 2 after the postfix update; the loop adds 0 + 1 + 2.
    { type: 'click', selector: '.add-sum' },
    { type: 'expectText', selector: '.log', text: '#1 #1 ba +5' },
    { type: 'expectText', selector: '.next', text: '0' },
  ],
}

export const fixture = defineSharedFixture(spec)
